import React from 'react';

import {
  mockPortfolioBigNumbers,
  mockPortfolioPieCharts,
} from './__mocks__/portfolioData.mock';
import { TotalInnovationPerformance } from './components';
import { InnovationPortfolio } from './components/InnovationPortfolio/InnovationPortfolio';
import { StyledOverviewRoot } from './Overview.styles';

interface OverviewProps {
  dataTestId?: string;
}

export const Overview: React.FC<OverviewProps> = ({ dataTestId }) => {
  const containerDataTestId = dataTestId
    ? `${dataTestId}-container`
    : 'innovation-hub-overview-container';

  return (
    <StyledOverviewRoot
      data-testid={containerDataTestId}
      data-full-width="true"
    >
      <TotalInnovationPerformance
        dataTestId={
          dataTestId
            ? `${dataTestId}-total-innovation-performance`
            : 'innovation-hub-overview-total-innovation-performance'
        }
      />
      <InnovationPortfolio
        dataTestId={
          dataTestId
            ? `${dataTestId}-portfolio`
            : 'innovation-hub-overview-portfolio'
        }
        mockPortfolioBigNumbers={mockPortfolioBigNumbers}
        mockPortfolioPieCharts={mockPortfolioPieCharts}
      />
    </StyledOverviewRoot>
  );
};
